// Parse Product Hunt + Hacker News into normalized candidates
const candidates = [];
const errors = [];

// --- Product Hunt ---
try {
  const phRaw = $('PH: Top Posts').first().json;
  const edges = phRaw?.data?.posts?.edges || [];
  for (const edge of edges) {
    const post = edge.node;
    const makers = post.makers || [];
    // Only consider posts with 1-3 makers (small teams / solo builders)
    if (makers.length > 0 && makers.length <= 3) {
      for (const maker of makers) {
        candidates.push({
          name: maker.name || 'Unknown',
          twitter_handle: maker.twitterUsername || null,
          personal_url: maker.websiteUrl || null,
          signal_type: 'product-hunt-launch',
          signal_description: `Launched "${post.name}" on Product Hunt: ${post.tagline}. ${post.votesCount} upvotes. Team size: ${makers.length}.`,
          source: 'product-hunt',
          source_url: post.url || post.website || null,
          podcast_target: 'builder-economy',
          raw_data: { ph_post: post.name, votes: post.votesCount, headline: maker.headline }
        });
      }
    }
  }
} catch(e) {
  errors.push('Product Hunt parse error: ' + e.message);
}

// --- Hacker News ---
try {
  const hnRaw = $('HN: Show HN').first().json;
  const hits = hnRaw?.hits || [];
  for (const hit of hits) {
    if (hit.points >= 50) {
      candidates.push({
        name: hit.author || 'Unknown',
        twitter_handle: null,
        personal_url: hit.url || null,
        signal_type: 'show-hn-launch',
        signal_description: `Show HN: "${hit.title}". ${hit.points} points, ${hit.num_comments} comments.`,
        source: 'hacker-news',
        source_url: `https://news.ycombinator.com/item?id=${hit.objectID}`,
        podcast_target: 'builder-economy',
        raw_data: { hn_title: hit.title, points: hit.points, comments: hit.num_comments }
      });
    }
  }
} catch(e) {
  errors.push('Hacker News parse error: ' + e.message);
}

return [{ json: { be_candidates: candidates, be_count: candidates.length, be_errors: errors } }];

// --- injected AI body enrichment ---
const __origResult = (function(){

// Parse RSS XML from all three feeds, extract articles for AI extraction
const articles = [];
const feeds = [
  { name: 'Digiday', data: $('RSS: Digiday').first().json },
  { name: 'The Rebooting', data: $('RSS: Rebooting').first().json },
  { name: 'NiemanLab', data: $('RSS: NiemanLab').first().json },
];

function parseRSS(xml, sourceName) {
  if (typeof xml !== 'string') {
    // If response came as JSON (some N8N configs), try to get the text
    xml = xml?.data || xml?.body || JSON.stringify(xml);
  }
  const items = [];
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    const block = match[1];
    const title = (block.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [])[1] || '';
    const link = (block.match(/<link>([\s\S]*?)<\/link>/) || [])[1] || '';
    const desc = (block.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/) || [])[1] || '';
    const creator = (block.match(/<dc:creator>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/dc:creator>/) || [])[1] || '';
    if (title.trim()) {
      items.push({
        title: title.trim().replace(/<[^>]*>/g, ''),
        link: link.trim(),
        description: desc.replace(/<[^>]*>/g, '').trim().slice(0, 300),
        creator: creator.trim().replace(/<[^>]*>/g, ''),
        source: sourceName
      });
    }
  }
  return items.slice(0, 10); // Top 10 per feed
}

for (const feed of feeds) {
  try {
    const feedData = typeof feed.data === 'string' ? feed.data : (feed.data?.data || '');
    const parsed = parseRSS(feedData, feed.name);
    articles.push(...parsed);
  } catch(e) {
    articles.push({ title: `Error parsing ${feed.name}: ${e.message}`, source: feed.name });
  }
}

// Get BE candidates from upstream
const be = $('Parse BE Sources').first().json;

// Build AI extraction prompt
const articleSummary = articles
  .filter(a => a.title && a.link)
  .map((a, i) => `${i+1}. [${a.source}] "${a.title}" by ${a.creator || 'unknown'}: ${a.description || 'no description'}`)
  .join('\n');

const aiPrompt = `You are Nell, a podcast guest sourcing agent. Analyze these recent media/tech articles and extract any notable PERSON (executive, journalist, thought leader, analyst) who demonstrates a sharp viewpoint on AI transformation in media, publishing, or broadcasting.

Articles from today:
${articleSummary || 'No articles found today.'}

For each person you identify, return:
- name: their full name
- signal_description: why they would be a great guest (reference the specific article/viewpoint)
- source_url: the article URL
- twitter_handle: if inferrable from the byline or content, otherwise null

Return ONLY a JSON object: { "candidates": [ { "name": "...", "signal_description": "...", "source_url": "...", "twitter_handle": null } ] }

If no strong candidates are found, return { "candidates": [] }. Only include people who would have a genuinely interesting, non-obvious take. No generic executives.`;

return [{ json: {
  be_candidates: be.be_candidates,
  be_count: be.be_count,
  be_errors: be.be_errors,
  rss_article_count: articles.length,
  ai_prompt: aiPrompt
}}];

})();
const __enriched = (__origResult || []).map(item => {
  const j = item.json || {};
  const promptText = j.ai_prompt || '';
  const aBody = {
    model: 'claude-haiku-4-5',
    max_tokens: 2048,
    messages: [{ role: 'user', content: promptText }]
  };
  const gBody = {
    contents: [{ parts: [{ text: promptText }] }],
    generationConfig: { maxOutputTokens: 2048, responseMimeType: 'application/json' }
  };
  return { json: { ...j, anthropicBody: JSON.stringify(aBody), geminiBody: JSON.stringify(gBody) } };
});
return __enriched;

// Parse AI extraction response and merge with BE candidates
const upstream = $('Parse RSS + Prep AI').first().json;
const aiRaw = $('Merge AI: Anthropic: Extract People').first().json;
const allCandidates = [...upstream.be_candidates];

// Parse AI response
try {
  const text = aiRaw?.content?.[0]?.text || '';
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    const snCandidates = (parsed.candidates || []).map(c => ({
      name: c.name,
      twitter_handle: c.twitter_handle || null,
      personal_url: null,
      signal_type: 'rss-ai-extraction',
      signal_description: c.signal_description,
      source: 'rss-ai-extraction',
      source_url: c.source_url || null,
      podcast_target: 'signal-and-noise',
      raw_data: { extracted_from: 'rss_feeds' }
    }));
    allCandidates.push(...snCandidates);
  }
} catch(e) {
  // AI extraction failed, continue with BE candidates only
}

return [{ json: {
  all_candidates: allCandidates,
  total_count: allCandidates.length,
  be_count: upstream.be_count,
  sn_count: allCandidates.length - upstream.be_count,
  errors: upstream.be_errors || []
}}];

// Dedup: remove candidates already known in the `guests` table for the same
// show, across ALL statuses (incl. published/recorded past guests). Identity
// based (normalized name + email), source agnostic. Fixes the long-standing bug
// where this queried the dropped `nell_candidates` table and deduped vs nothing.
const upstream = $('Merge All Candidates').first().json;
function norm(s){
  return (s||'').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g,'')
    .replace(/[^a-z0-9]+/g,' ').trim();
}
let existing = [];
try {
  for (const item of $('Supabase: Get Existing').all()) {
    const d = item.json;
    if (Array.isArray(d)) existing.push(...d);
    else if (d && d.name) existing.push(d);
  }
} catch (e) {}
const nameTargets = new Map();
const emailSet = new Set();
for (const e of existing) {
  const nm = norm(e.name);
  if (nm) { if (!nameTargets.has(nm)) nameTargets.set(nm, new Set()); nameTargets.get(nm).add(e.podcast_target || null); }
  if (e.email) emailSet.add(String(e.email).toLowerCase().trim());
}
const seenThisRun = new Set();
const newCandidates = (upstream.all_candidates || []).filter(c => {
  const nm = norm(c.name);
  const tgt = c.podcast_target || null;
  const email = (c.email || '').toLowerCase().trim();
  const known = (nameTargets.has(nm) && (nameTargets.get(nm).has(tgt) || nameTargets.get(nm).has(null)))
             || (email && emailSet.has(email));
  if (known) return false;
  const runKey = nm + '|' + tgt;
  if (seenThisRun.has(runKey)) return false;
  seenThisRun.add(runKey);
  return true;
});
return [{ json: {
  new_candidates: newCandidates,
  new_count: newCandidates.length,
  filtered_count: (upstream.all_candidates || []).length - newCandidates.length,
  total_scanned: upstream.total_count,
  be_count: upstream.be_count,
  sn_count: upstream.sn_count,
  existing_in_db: existing.length,
  errors: upstream.errors
}}];

// --- injected AI body enrichment ---
const __origResult = (function(){

// Build scoring prompt for all new candidates — NEW editorial bar:
// emits target_type + skip_reason so the router can fan out into
// guests / visibility_targets / nell_rejected.

const upstream = $('Dedup Candidates').first().json;
const candidates = upstream.new_candidates;

if (!candidates || candidates.length === 0) {
  return [{ json: { scored: [], qualified: [], digest: 'No new candidates to score.' } }];
}

const candidateList = candidates.map((c, i) =>
  `${i+1}. Name: ${c.name} | Podcast: ${c.podcast_target} | Source: ${c.source} | Signal: ${c.signal_description}`
).join('\n');

const prompt = `You are Nell, a podcast guest sourcing agent for Krish Raja. Apply a strict editorial bar.

Krish runs two podcasts:
- The Built (thebuildereconomy.com): founders, CTOs, Heads of AI, operators shipping AI infrastructure or AI-native products with traction, distribution, or a documented strategic POV.
- Signal & Noise (signalandnoise.ai): operators, founders, executives in media, publishing, broadcast, adtech, AI-for-media infra. Decision-makers with a public POV.

Press targets are different. Reporters, correspondents, columnists, editors, anchors at named outlets (Digiday, WSJ, BBC, NYT, Bloomberg, Axios, Reuters, The Atlantic, The Guardian, Vox, The Verge, Wired, TechCrunch, Forbes, FT, The Economist, NiemanLab, Wirecutter, The Information). These should be visibility_targets press_relationships, not guests.

Dual is rare: someone who could realistically appear on the show AND feature Krish in their channel.

For each candidate, return STRICT JSON:
{
  "scores": [
    {
      "index": 1,
      "name": "...",
      "target_type": "podcast_guest" | "press_target" | "dual",
      "podcast_target": "built" | "signal_noise" | null,
      "press_publication": "string | null",
      "fit_score": 1-10,
      "attainability_score": 1-10,
      "quality_signals": ["one signal", "another"],
      "contact_method": "email" | "linkedin" | "twitter" | "none",
      "suggested_channel": "email | linkedin | twitter | contact-form",
      "reasoning": "one sentence why",
      "skip_reason": "string | null"
    }
  ]
}

Skip rules — set skip_reason and the row will be silently logged, not surfaced:
- Name looks like an HN username (lowercase alphanumeric, no real first/last name resolvable): skip_reason = "hn-username-no-real-name"
- contact_method = "none" AND target_type = "podcast_guest": skip_reason = "no-verifiable-contact"
- target_type = "podcast_guest" AND podcast_target = "built" AND fit_score < 6: skip_reason = "below-builder-economy-fit-bar"
- target_type = "podcast_guest" AND podcast_target = "signal_noise" AND fit_score < 7: skip_reason = "below-signal-noise-fit-bar"
- One Show HN post alone is not qualification for built. The bar is durable building, not a viral post. If the only evidence is a Show HN ranking: skip_reason = "hn-post-only-not-durable-builder"

Candidates:
${candidateList}

Return ONLY JSON. No prose.`;

return [{ json: {
  candidates: candidates,
  scoring_prompt: prompt,
  metadata: { new_count: upstream.new_count, filtered_count: upstream.filtered_count, total_scanned: upstream.total_scanned }
}}];


})();
const __enriched = (__origResult || []).map(item => {
  const j = item.json || {};
  const promptText = j.scoring_prompt || '';
  const aBody = {
    model: 'claude-haiku-4-5',
    max_tokens: 4096,
    messages: [{ role: 'user', content: promptText }]
  };
  const gBody = {
    contents: [{ parts: [{ text: promptText }] }],
    generationConfig: { maxOutputTokens: 4096, responseMimeType: 'application/json' }
  };
  return { json: { ...j, anthropicBody: JSON.stringify(aBody), geminiBody: JSON.stringify(gBody) } };
});
return __enriched;

// Parse scores from the new editorial-bar prompt, bucket into:
//   qualified_guests  -> guests table (podcast_guest, dual; fit/attain >= bar)
//   qualified_press   -> visibility_targets table (press_target, dual)
//   rejected          -> nell_rejected table (any skip_reason set, or below bar)

const upstream = $('Prep Scoring Prompt').first().json;
const aiRaw = $('Merge AI: Anthropic: Score').first().json;
const candidates = upstream.candidates;
const metadata = upstream.metadata;

let scores = [];
try {
  const text = aiRaw?.content?.[0]?.text || '';
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    scores = JSON.parse(jsonMatch[0]).scores || [];
  }
} catch(e) {
  return [{ json: { qualified_guests: [], qualified_press: [], rejected: [], error: 'Score parse failed: ' + e.message, metadata } }];
}

const qualified_guests = [];
const qualified_press = [];
const rejected = [];

for (const score of scores) {
  const idx = (score.index || 1) - 1;
  const candidate = candidates[idx];
  if (!candidate) continue;

  const target_type = score.target_type || 'podcast_guest';
  const podcast_target = score.podcast_target || candidate.podcast_target;
  const fit_score = Number(score.fit_score) || 0;
  const attainability_score = Number(score.attainability_score) || 0;
  const contact_method = score.contact_method || 'none';
  const skip_reason = score.skip_reason || null;

  const merged = {
    ...candidate,
    target_type,
    podcast_target,
    press_publication: score.press_publication || null,
    fit_score,
    attainability_score,
    contact_method,
    best_channel: score.suggested_channel || 'linkedin',
    notes: score.reasoning || '',
    quality_signals: score.quality_signals || [],
    skip_reason
  };

  if (skip_reason) {
    rejected.push(merged);
    continue;
  }

  if (target_type === 'press_target') {
    qualified_press.push(merged);
  } else if (target_type === 'dual') {
    qualified_press.push(merged);
    if (fit_score >= 6 && attainability_score >= 6) qualified_guests.push(merged);
  } else {
    // podcast_guest path
    const bar = podcast_target === 'signal_noise' ? 7 : 6;
    if (fit_score >= bar && attainability_score >= 6 && contact_method !== 'none') {
      qualified_guests.push(merged);
    } else {
      merged.skip_reason = 'below-bar-or-no-contact';
      rejected.push(merged);
    }
  }
}

return [{ json: {
  qualified_guests,
  qualified_press,
  rejected,
  qualified_guests_count: qualified_guests.length,
  qualified_press_count: qualified_press.length,
  rejected_count: rejected.length,
  // Legacy keys preserved so downstream Build Digest / Split Candidates keep working:
  qualified: qualified_guests,
  qualified_count: qualified_guests.length,
  disqualified: rejected,
  disqualified_count: rejected.length,
  metadata
}}];

// Insert router: writes qualified_guests -> guests, qualified_press -> visibility_targets,
// rejected -> nell_rejected. Uses this.helpers.httpRequest (n8n's HTTP helper) — the
// previous global fetch() is not defined in this runtime, so every run with new
// candidates errored before inserting (inbound never replenished). Downstream HTTP
// nodes are left in place but receive insert_body='[]' so they no-op.
//
// guests.status must be 'scouted' (was 'new', which violates guests_status_check) and
// guests.source must be one of manual/sheet_import/nell_outbound/referral/migration
// (guests_source_check) — so qualified guests use 'nell_outbound'.

const upstream = $('Parse Scores + Filter').first().json;
const guests = upstream.qualified_guests || [];
const press  = upstream.qualified_press  || [];
const rej    = upstream.rejected         || [];

const SUPA = "https://gojpffsrxybbpbdzzrvs.supabase.co";
const KEY  = "{{SUPABASE_SERVICE_ROLE_KEY}}";

const httpRequest = this.helpers.httpRequest.bind(this.helpers);

async function insertMany(path, rows) {
  if (!rows || !rows.length) return { ok: true, status: 200, body: '[]' };
  try {
    const resp = await httpRequest({
      method: 'POST',
      url: `${SUPA}/rest/v1/${path}`,
      headers: {
        apikey: KEY,
        Authorization: `Bearer ${KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
      },
      body: rows,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 20000
    });
    return { ok: resp.statusCode >= 200 && resp.statusCode < 300, status: resp.statusCode, body: (typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body || '')).slice(0, 400) };
  } catch (e) {
    return { ok: false, status: e.statusCode || e.httpCode || 0, body: String(e.message || e).slice(0, 400) };
  }
}

const guestRows = guests.map(c => ({
  name: c.name,
  email: c.email || null,
  linkedin_url: c.linkedin_url || null,
  twitter_handle: c.twitter_handle || null,
  personal_url: c.personal_url || null,
  podcast_target: c.podcast_target,
  target_type: c.target_type,
  one_liner: c.signal_description || null,
  why_fit: c.notes || null,
  best_channel: c.best_channel,
  fit_score: c.fit_score,
  attainability_score: c.attainability_score,
  quality_score: (c.fit_score >= 8 && c.attainability_score >= 8) ? 'green'
    : (c.fit_score >= 6 && c.attainability_score >= 6) ? 'amber' : 'red',
  status: 'scouted',
  source: 'nell_outbound',
  raw_data: JSON.stringify({ ...(typeof c.raw_data === 'string' ? JSON.parse(c.raw_data || '{}') : (c.raw_data || {})), upstream_source: c.source })
}));

const pressRows = press.map(c => ({
  title: c.press_publication
    ? `${c.name} — ${c.press_publication}`
    : c.name,
  type: 'press_relationship',
  source_url: c.source_url || c.linkedin_url || c.personal_url || null,
  why_relevant: c.notes || c.signal_description || null,
  status: 'queued',
  source: 'nell-scout',
  quality_score: (c.fit_score >= 8) ? 'green' : (c.fit_score >= 6) ? 'amber' : 'red',
  relevance_score: c.fit_score || null,
  raw_data: { person: c.name, source: c.source, signals: c.quality_signals || [], notes: c.notes }
}));

const rejRows = rej.map(c => ({
  name: c.name,
  source_url: c.source_url || null,
  source: 'nell_outbound',
  upstream_source: c.source,
  reason: c.skip_reason || 'unspecified',
  raw_data: { signals: c.quality_signals || [], notes: c.notes, target_type: c.target_type, fit_score: c.fit_score }
}));

const [gRes, pRes, rRes] = await Promise.all([
  insertMany('guests', guestRows),
  insertMany('visibility_targets', pressRows),
  insertMany('nell_rejected', rejRows)
]);

return [{ json: {
  // legacy key so downstream Build Digest keeps working with an empty no-op insert body:
  insert_body: '[]',
  // qualified_rows carries the real guest rows downstream. insert_body is a
  // deliberate no-op for the legacy HTTP node, so Filter vs Contacted must NOT
  // reconstruct from it or the pitch last-mile silently receives zero.
  qualified_rows: guests,
  qualified_count: guestRows.length,
  qualified_press_count: pressRows.length,
  rejected_count: rejRows.length,
  qualified_summary: guests.map(c => ({
    name: c.name, target_type: c.target_type, podcast: c.podcast_target,
    fit: c.fit_score, attain: c.attainability_score, channel: c.best_channel
  })),
  press_summary: press.map(c => ({ name: c.name, outlet: c.press_publication, fit: c.fit_score })),
  rejected_summary: rej.map(c => ({ name: c.name, reason: c.skip_reason })),
  insert_status: { guests: gRes, press: pRes, rejected: rRes },
  metadata: upstream.metadata
}}];

// Build Telegram digest (reads filtered qualified list)
const upstream = $('Filter vs Contacted').first().json;
const meta = upstream.metadata || {};
const summary = upstream.qualified_summary || [];
const qCount = upstream.qualified_count || 0;
const dCount = upstream.disqualified_count || 0;
const skipped = meta.skipped_already_contacted || 0;
const now = new Date().toISOString().split('T')[0];

const beSummary = summary.filter(s => s.podcast === 'builder-economy');
const snSummary = summary.filter(s => s.podcast === 'signal-and-noise');

let lines = [];
lines.push('🎯 <b>Nell Guest Scout</b>');
lines.push('');
lines.push('📅 ' + now);
lines.push('🔍 ' + (meta.total_scanned || 0) + ' scanned • ' + (meta.filtered_count || 0) + ' dupes skipped');
lines.push('✅ ' + qCount + ' qualified • ❌ ' + dCount + ' below threshold');
if (skipped > 0) lines.push('⏭️ ' + skipped + ' skipped (contacted in last 7d)');

if (beSummary.length > 0) {
  lines.push('');
  lines.push('🛠️ <b>Built</b> (' + beSummary.length + ')');
  lines.push('');
  for (const s of beSummary) {
    lines.push('▶ <b>' + s.name + '</b>  [' + s.fit + '/' + s.attain + ']  via ' + s.channel);
    if (s.signal) lines.push('  <i>' + s.signal + '</i>');
  }
}

if (snSummary.length > 0) {
  lines.push('');
  lines.push('📡 <b>Signal & Noise</b> (' + snSummary.length + ')');
  lines.push('');
  for (const s of snSummary) {
    lines.push('▶ <b>' + s.name + '</b>  [' + s.fit + '/' + s.attain + ']  via ' + s.channel);
    if (s.signal) lines.push('  <i>' + s.signal + '</i>');
  }
}

if (qCount === 0) {
  lines.push('');
  lines.push('No new candidates to pitch today.');
}

lines.push('');
lines.push('────────────────────────');
lines.push('📧 Drafts created in Gmail • DB: <code>nell_candidates</code>');

return [{ json: {
  telegram_text: lines.join('\n'),
  qualified_count: qCount,
  disqualified_count: dCount,
  skipped_contacted: skipped,
  total_scanned: meta.total_scanned || 0
} }];

const upstream = $('Dedup Candidates').first().json;
const now = new Date().toISOString().split('T')[0];

let lines = [];
lines.push('🎯 <b>Nell Daily Guest Scout</b>');
lines.push('');
lines.push(`📅 ${now}`);
lines.push(`🔍 ${upstream.total_scanned || 0} scanned`);
lines.push('');
lines.push('All candidates already in database.');
lines.push('No new entries to score today.');

return [{ json: { telegram_text: lines.join('\n') } }];

// Parse Apollo enrichment results. Runs once for ALL items.
// Apollo: Enrich emits one item per candidate. Its key can be dead (401), and
// onError=continueRegularOutput turns that into an {error:...} item rather than
// a throw, so enrichment MUST degrade gracefully instead of breaking the pitch
// chain. A failed enrichment keeps status 'scouted' so we never claim a contact
// was enriched when it was not.
const inputs = $input.all();
let apolloItems = [];
try { apolloItems = $('Apollo: Enrich').all(); } catch (e) { apolloItems = []; }

return inputs.map((item, i) => {
  const base = item.json || {};
  const raw = apolloItems[i]?.json || {};
  const failed = !!raw.error;
  const person = (!failed && (raw.person || raw.data)) || {};
  const email = person.email || base.email || null;
  const linkedin = person.linkedin_url || base.linkedin_url || null;
  return { json: {
    ...base,
    email,
    linkedin_url: linkedin,
